def groupQueries(n, ops):
    parent = list(range(n))
    size = [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    out = []
    for t, a, b in ops:
        ra = find(a)
        if t == 1:
            rb = find(b)
            if ra != rb:
                if size[ra] < size[rb]:
                    ra, rb = rb, ra
                parent[rb] = ra
                size[ra] += size[rb]
        elif t == 2:
            out.append(size[ra])
        else:
            out.append(1 if ra == find(b) else 0)
    return out
